// Asset One logical asset (task 156): the group root carrying targets, exposure and asset class, with group-level computed fields (valuePln = Σ subassets, deviationPct on the asset) and the member subassets, primary first. Unique on (key, portfolio).
type Asset struct {
	AssetClass AssetClass `json:"assetClass"`

	// Computed Group-level computed fields, resolved at query time from live prices and the current macro blend state; never stored. `valuePln` = Σ over the asset's priced subassets; `unitsTotal`/`pricePln`/`priceNative` describe the primary subasset; `profitPct`, `avgBuyPricePln`, `avgBuyPriceNative`, `equivalentUnits` and `costlessSubassets` are the asset-level cost group (task 161): they read the SUM of the recorded costs (`totalSpentPln > 0`) over all subassets of the asset — never a single row's cost and never the stored `avgBuyPrice` — and are all null (or omitted) when no cost is recorded. Every field is optional/nullable; a client treats an absent field as null.
	Computed  *PositionComputed `json:"computed,omitempty"`
	CreatedAt *time.Time        `json:"createdAt,omitempty"`

	// Exposure Economic theme (CRYPTO, METALS, BONDS, EXPERIMENTS, EQUITY, ...).
	Exposure string `json:"exposure"`
	Id       *int64 `json:"id,omitempty"`

	// Key Stable logical slug, unique per portfolio (e.g. `bitcoin`, `gold`; a single-holding asset uses its holding's ticker). Never derive it from a subasset ticker — the primary can change.
	Key       string      `json:"key"`
	Name      string      `json:"name"`
	Portfolio Portfolio   `json:"portfolio"`
	Subassets *[]Subasset `json:"subassets,omitempty"`

	// TargetAllocationPct Risk-on-regime target allocation pct (blend=1, ADR-071 — was blend=0 under the original ADR-044 orientation). Since ADR-044, MAIN assets' effective rebalancing target interpolates this with targetAllocationPctRiskOff via the macro blend factor (GET /market-data/macro-state); this stored value is the risk-on endpoint of that interpolation, not necessarily the value actually used to plan the next purchase session. This is also the value the "Cel %" inline editor mutates via PUT /assets/{id} — see computed.effectiveTargetAllocationPct for the actual blended number to display as "the" target.
	TargetAllocationPct *float64 `json:"targetAllocationPct,omitempty"`

	// TargetAllocationPctRiskOff Risk-off-regime target allocation pct (blend=0, ADR-071 — was blend=1 under the original ADR-044 orientation), added ADR-044. Null means "identical to targetAllocationPct" (most assets — gold, the Experiments sleeve — do not move between regimes). Never read for RETIREMENT assets.
	TargetAllocationPctRiskOff *float64   `json:"targetAllocationPctRiskOff,omitempty"`
	UpdatedAt                  *time.Time `json:"updatedAt,omitempty"`
}

